"use client";

import { useState, FormEvent } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { auth } from "@/lib/firebaseConfig";
import { isAdminEmail } from "@/lib/adminAuth";

// Mensagens amigáveis para as falhas mais comuns do login com Google.
const GOOGLE_ERROS: Record<string, string> = {
  "auth/unauthorized-domain":
    "Este domínio não está autorizado no Firebase. Adicione-o em Authentication → Settings → Authorized domains.",
  "auth/popup-blocked": "O navegador bloqueou o pop-up. Permita pop-ups para este site e tente de novo.",
  "auth/popup-closed-by-user": "Você fechou a janela antes de concluir. Tente novamente.",
  "auth/cancelled-popup-request": "Login cancelado. Tente novamente.",
  "auth/operation-not-allowed": "O provedor Google não está habilitado no Firebase Authentication.",
  "permission-denied": "Login OK, mas o Firestore bloqueou a gravação do perfil. Ajuste as Regras do Firestore.",
};

export default function AdminLoginPage() {
  const router = useRouter();
  const { loginWithGoogle } = useAuth();
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [googleBusy, setGoogleBusy] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const res = await fetch("/api/admin/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });
      if (!res.ok) {
        const data = await res.json();
        setError(data.error ?? "Erro ao fazer login.");
      } else {
        router.push("/admin/dashboard");
      }
    } catch {
      setError("Erro de conexão. Tente novamente.");
    } finally {
      setLoading(false);
    }
  }

  async function handleGoogle() {
    setError("");
    setGoogleBusy(true);
    try {
      await loginWithGoogle();
      const email = auth.currentUser?.email ?? "";
      if (isAdminEmail(email)) {
        router.push("/admin/dashboard");
      } else {
        setError(`A conta ${email || "selecionada"} não tem permissão de professor.`);
      }
    } catch (err) {
      const code = (err as { code?: string })?.code ?? "";
      console.error("[admin] login Google falhou:", err);
      setError(GOOGLE_ERROS[code] ?? `Não foi possível entrar com o Google.${code ? ` (${code})` : ""}`);
    } finally {
      setGoogleBusy(false);
    }
  }

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "var(--dark-1)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "2rem",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "400px",
          background: "var(--dark-2)",
          border: "1px solid rgba(255,85,0,0.2)",
          borderRadius: "20px",
          padding: "3rem 2.5rem",
          boxShadow: "0 0 60px rgba(255,85,0,0.06)",
        }}
      >
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: "2.5rem" }}>
          <span style={{ fontSize: "2.5rem", display: "block", marginBottom: "0.75rem" }}>🔥</span>
          <h1
            style={{
              fontFamily: "var(--font-display)",
              fontSize: "1.8rem",
              letterSpacing: "0.1em",
              color: "var(--text-primary)",
              marginBottom: "0.25rem",
            }}
          >
            PAINEL ADMIN
          </h1>
          <p style={{ fontSize: "0.82rem", color: "var(--text-muted)" }}>
            Web On Fire Academy
          </p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: "1.25rem" }}>
            <label
              htmlFor="password"
              style={{
                display: "block",
                fontSize: "0.75rem",
                fontFamily: "var(--font-mono)",
                color: "rgba(255,119,68,0.8)",
                letterSpacing: "0.08em",
                textTransform: "uppercase",
                marginBottom: "0.5rem",
              }}
            >
              Senha de acesso
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              required
              className="input-field"
              style={{ fontSize: "1rem", letterSpacing: "0.1em" }}
            />
          </div>

          {error && (
            <div
              style={{
                background: "rgba(204,34,0,0.08)",
                border: "1px solid rgba(204,34,0,0.3)",
                borderRadius: "8px",
                padding: "0.75rem 1rem",
                fontSize: "0.82rem",
                color: "#FF6644",
                marginBottom: "1.25rem",
              }}
            >
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading || !password}
            className="fire-btn"
            style={{
              width: "100%",
              padding: "0.9rem",
              borderRadius: "10px",
              fontSize: "0.9rem",
              fontWeight: 700,
              letterSpacing: "0.06em",
              color: "#fff",
              fontFamily: "inherit",
              opacity: loading || !password ? 0.6 : 1,
              cursor: loading || !password ? "not-allowed" : "pointer",
            }}
          >
            {loading ? "Entrando..." : "🔥 ENTRAR COM SENHA"}
          </button>
        </form>

        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", margin: "1.5rem 0" }}>
          <div style={{ flex: 1, height: "1px", background: "rgba(255,255,255,0.08)" }} />
          <span style={{ fontSize: "0.7rem", color: "var(--text-muted)", fontFamily: "var(--font-mono)" }}>ou</span>
          <div style={{ flex: 1, height: "1px", background: "rgba(255,255,255,0.08)" }} />
        </div>

        <button
          type="button"
          onClick={handleGoogle}
          disabled={googleBusy}
          style={{
            width: "100%",
            padding: "0.85rem",
            borderRadius: "10px",
            background: "rgba(255,255,255,0.04)",
            border: "1px solid rgba(255,255,255,0.1)",
            color: "rgba(255,255,255,0.85)",
            fontSize: "0.86rem",
            fontWeight: 600,
            fontFamily: "inherit",
            cursor: googleBusy ? "wait" : "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: "0.6rem",
          }}
        >
          <span style={{ fontWeight: 800 }}>G</span>
          {googleBusy ? "Entrando..." : "Entrar como professor (Google)"}
        </button>
        <p style={{ textAlign: "center", marginTop: "0.75rem", fontSize: "0.7rem", color: "rgba(255,255,255,0.3)", lineHeight: 1.5 }}>
          Use a conta de professor autorizada (emanoelsp@gmail.com)
        </p>

        <p
          style={{
            textAlign: "center",
            marginTop: "2rem",
            fontSize: "0.75rem",
            color: "rgba(255,255,255,0.15)",
            fontFamily: "var(--font-mono)",
          }}
        >
          Acesso restrito ao administrador
        </p>
      </div>
    </main>
  );
}
